actions.command:
/bin/zsh -c "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { Schema, Either } from 'effect';
import { manifestSchema, importManifest } from './dist/index.js';
const parcel = { reference: ' p1 ', grams: 1, service: 'standard' };
const valid = { partner: ' shop ', parcels: [parcel, { reference: 'p2', grams: 300, service: 'express' }], extra: { ignored: true } };
const expected = { partner: 'shop', parcels: [{ reference: 'p1', grams: 1, service: 'standard' }, { reference: 'p2', grams: 300, service: 'express' }] };
const snapshot = structuredClone(valid);
const decoded = Schema.decodeUnknownEither(manifestSchema)(valid);
assert.ok(Either.isRight(decoded));
assert.deepEqual(decoded.right, expected);
const result = importManifest(valid);
assert.deepEqual(result, { ok: true, manifest: expected });
assert.deepEqual(valid, snapshot);
assert.notStrictEqual(result.manifest, valid);
assert.notStrictEqual(result.manifest.parcels, valid.parcels);
assert.notStrictEqual(result.manifest.parcels[0], parcel);
parcel.reference = 'changed';
valid.parcels.push({ reference: 'p3', grams: 5, service: 'standard' });
assert.deepEqual(result.manifest, expected);
const invalid = [undefined, null, true, 1, 'manifest', [], {}, { partner: 'shop' }, { parcels: [parcel] }, { partner: ' ', parcels: [parcel] }, { partner: 1, parcels: [parcel] }, { partner: 'shop', parcels: [] }, { partner: 'shop', parcels: {} }];
for (const grams of [undefined, null, '1', NaN, Infinity, -Infinity, 0, -1, 1.5]) invalid.push({ partner: 'shop', parcels: [{ reference: 'p1', grams, service: 'standard' }] });
for (const reference of [undefined, null, 1, ' ', '']) invalid.push({ partner: 'shop', parcels: [{ reference, grams: 1, service: 'standard' }] });
for (const service of [undefined, null, 1, 'overnight', ' standard ']) invalid.push({ partner: 'shop', parcels: [{ reference: 'p1', grams: 1, service }] });
invalid.push({ partner: 'shop', parcels: [{ reference: ' p1 ', grams: 1, service: 'standard' }, { reference: 'p1', grams: 2, service: 'express' }] });
for (const input of invalid) {
  assert.ok(Either.isLeft(Schema.decodeUnknownEither(manifestSchema)(input)));
  assert.deepEqual(importManifest(input), { ok: false, reason: 'invalid-manifest' });
}
const withExtras = { partner: 'shop', parcels: [{ reference: 'p1', grams: 1, service: 'standard', extra: {} }] };
assert.deepEqual(Schema.decodeUnknownSync(manifestSchema)(withExtras), { partner: 'shop', parcels: [{ reference: 'p1', grams: 1, service: 'standard' }] });
console.log("'`Direct decoder and importer checks passed for normalization, isolation, field stripping, and ${invalid.length} invalid inputs.`);
JS'

changes.before:
import { Schema } from "effect";
import type { PartnerManifest } from "./types.js";
export const manifestSchema: Schema.Schema<PartnerManifest, unknown> = Schema.Unknown as Schema.Schema<PartnerManifest, unknown>;

changes.after:
import { Schema } from "effect";
const nonBlankString = Schema.Trim.pipe(Schema.nonEmptyString());
const parcelSchema = Schema.Struct({
  reference: nonBlankString,
  grams: Schema.Number.pipe(Schema.finite(), Schema.int(), Schema.positive()),
  service: Schema.Literal("standard", "express")
});

export const manifestSchema = Schema.Struct({
  partner: nonBlankString,
  parcels: Schema.Array(parcelSchema).pipe(Schema.minItems(1))
}).pipe(
  Schema.filter(({ parcels }) => new Set(parcels.map(({ reference }) => reference)).size === parcels.length)
);
